  ('i-schdee-auf-di', 'I schdee auf di!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich steh auf dich!', '[{"kategorie": "wörtlich", "text": "\"Ich steh auf dich!\"  2. Ich hab dich lieb!  3. Ich hab dich gern!  4. Ich hab dich zum Fressen gern! (Im Wienerischen bekundet man seine Liebe nicht mit den Worten \"Ich liebe dich!\", sondern vielmehr mit Wendungen wie [[I hob di gean!]], [[I foa oo auf di!]], [[Du gfoist ma!]] oder [[I mog di!]])"}]'::jsonb, 'I hob di gean!'),
  ('i-foa-oo-auf-di', 'I foa oo auf di!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich fahr ab auf dich!', '[{"kategorie": "wörtlich", "text": "\"Ich fahre ab auf dich!\"  2. Ich hab dich zum Fressen gern!  3. Ich hab dich lieb!  4. Ich hab dich gern!  4.  (Im Wienerischen bekundet man seine Liebe nicht mit den Worten \"Ich liebe dich!\", sondern vielmehr mit Wendungen wie [[I hob di gean!]], [[I mog di!]], [[I schdee auf di!]] oder [[Du gfoist ma!]])"}]'::jsonb, 'I hob di gean!'),
  ('du-gfoist-ma', 'Du gfoist ma!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Du gefällst mir!', '[{"kategorie": "wörtlich", "text": "\"Ich mag dich!  2. Du bist genau mein Typ!  3. Ich hab dich gern!  4. Du bedeutest mir was! (Im Wienerischen bekundet man seine Liebe nicht mit den Worten \"Ich liebe dich!\", sondern vielmehr mit Wendungen wie [[I hob di gean!]], [[I mog di!]], [[I schdee auf di!]] oder [[I foa oo auf di!]])"}]'::jsonb, 'I hob di gean!'),
  ('wem-gean-haum', 'wem gean haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden gernhaben', '[{"kategorie": "wörtlich", "text": "\"jemanden lieben\" (Kompositum aus dem Adverb \"gern\"=\"lieb\" und dem Verb \"haben\"=\"innehaben\")"}, {"kategorie": "allg.", "text": "jemanden mögen, lieb haben, hochschätzen, verehren"}]'::jsonb, 'I hob si gean, owa heiratn tua is ned!'),
  ('wem-geanhaum-kenna', 'wem geanhaum kenna', '', '', '', '', 'jemanden gernhaben können', '[{"kategorie": "wörtlich", "text": "\"jemanden liebhaben können\""}, {"kategorie": "fig.", "text": "jemandem den Buckel runterrutschen können"}, {"kategorie": "", "text": "jemandem gestohlen bleiben können"}]'::jsonb, 'Hob mi gean!'),
  ('waunnst-mi-ned-gean-host-daunn-hob-mi-gean', 'Waunnst mi ned gean host, daunn hob mi gean!', '', '', '', '', 'Wenn du mich nicht gern hast, dann hab mich gern!', '[{"kategorie": "wörtlich", "text": "\"Wenn du mich nicht liebst, dann kannst du mich gernhaben!\"  2. Wenn du mich nicht liebst, dann rutsch mir doch den Buckel runter!  3. Wenn du mich nicht liebst, dann kannst du mir gestohlen bleiben!"}]'::jsonb, 'wem gean haum'),
  ('hob-mi-gean', 'Hob mi gean!', '', '', '', '', 'Habe mich gerne!', '[{"kategorie": "", "text": "Du kannst mich mal gernhaben!  2. Du kannst mir den Buckel runterrutschen!  3. Du kannst mir gestohlen bleiben!  4. Lass mich in Ruhe!  5. Geh mir aus den Augen!"}]'::jsonb, 'wem geanhaum kenna'),
  ('du-kaunnst-mi-gean-haum', 'Du kaunnst mi gean haum!', '', '', '', '', 'Du kannst mich gerne haben!', '[{"kategorie": "wörtlich", "text": "\"Du kannst mich mal lieb haben!\"  2. (fig.) Du kannst mir den Buckel runterrutschen!  3. Du kannst mich mal!"}]'::jsonb, ''),
  ('amoi-umfoin', 'amoi umfoin', '', '', '', 'Wiener Sprüche, die sitzen!', 'einmal umfallen', '[{"kategorie": "adverbiell", "text": "\"nur ein Katzensprung\""}, {"kategorie": "", "text": "gleich um die Ecke"}, {"kategorie": "", "text": "ganz nahe"}, {"kategorie": "", "text": "in unmittelbarer Nähe"}]'::jsonb, 'Bis zu mia dahaam is nua amoi umfoin!'),
