  ('dahaam1', 'dahaam1', '', '', '', 'Grundwortschatz Wienerisch', 'daheim', '[{"kategorie": "wörtlich", "text": "\"daheim\" (vom mittelhochdeutschen \"dā heime\"=\"daheim\")"}, {"kategorie": "allg.", "text": "zuhause, im eigenen Heim, in den eigenen vier Wänden"}]'::jsonb, 'Dahaam is dahaam!'),
  ('so-nimm-da-doch-a-gscheids-schdickl-von-da-tuatn', 'So nimm da doch a gscheids Schdickl von da Tuatn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'So nimm dir doch ein gescheites Stück von der Torte!', '[{"kategorie": "wörtlich", "text": "\"So nimm dir doch ein ordentlich großes Stück von der Torte!\"  2. Greif ruhig ordentlich zu – schnapp dir ein schönes großes Stück Torte!  3. Na los, nimm dir ein richtig gescheites Stück von der Torte!"}]'::jsonb, ''),
  ('den-sei-ignoranz-reegd-mi-gscheid-auf', 'Den sei Ignoranz reegd mi gscheid auf!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seine Ignoranz regt mich gescheit auf!', '[{"kategorie": "wörtlich", "text": "\"Seine Ignoranz regt mich ganz besonders auf!\"  2. Seine Ignoranz bringt mich auf die Palme!  3. Seine Ignoranz regt mich über alle Maßen auf!"}]'::jsonb, ''),
