  ('dea-ghead-ghaud', 'Dea ghead ghaud!', '', '', '', '', 'Der gehört gehaut!', '[{"kategorie": "", "text": "Der gehört verhauen!  2. Dem gebührt eine Abreibung!  3. Der verdient eine Tracht Prügel!"}]'::jsonb, ''),
  ('dea-wiad-weng-an-jeedn-schaas-zum-gifthaeaefal', 'Dea wiad weng an jeedn Schaas zum Gifthääfal!', '', '', '', '', 'Der wird wegen jedem Schas zum Gifthäferl!', '[{"kategorie": "", "text": "Der geht bei der kleinsten Kleinigkeit gleich hoch!  2. Der kocht bei jedem kleinen Anlass über!  3. Der flippt wegen jeder Kleinigkeit aus!"}]'::jsonb, ''),
