  ('do-kriagst-de-pockalfraas', 'Do kriagst de Pockalfraas!', '', '', '', '', 'Da kriegst du die Pockerlfraisen!', '[{"kategorie": "", "text": "Da kriegst du Schaum vorm Mund\"!  2. Da zuckst du aus vor Ärger!  3. Da gehst du vor Wut in die Luft!"}]'::jsonb, ''),
