  ('des-baumpaletsch-growaed-scho-wiida-untan-tisch', 'Des Baumpaletsch growäd scho wiida untan Tisch!', '', '', '', '', 'Das Bamperletsch krabbelt schon wieder unter den Tisch!', '[{"kategorie": "wörtlich", "text": "\"Das Butzerl krabbelt schon wieder unter den Tisch!\"  2. Der Knirps kriecht schon wieder unter den Tisch!  3. Der kleine Racker robbt sich schon wieder unter den Tisch!"}]'::jsonb, ''),
  ('in-mei-toschn-brauchsd-ma-ned-growaen', 'In mei Toschn brauchsd ma ned growän!', '', '', '', '', 'In meine Tasche brauchst du mir nicht zu grabbeln!', '[{"kategorie": "wörtlich", "text": "\"In meiner Tasche brauchst du nicht zu wühlen!\"  2. Hände weg von meiner Tasche!  3. Lass die Finger aus meiner Tasche!"}]'::jsonb, ''),
