  ('dea-is-und-bleibd-a-klaana-growla', 'Dea is und bleibd a klaana Growla!', '', '', '', '', 'Der ist und bleibt ein kleiner Grabbler!', '[{"kategorie": "wörtlich", "text": "\"Der ist und bleibt ein ewiger Underdog!\"  2. Der ist und bleibt ein kleiner Fisch im großen Teich!  3. Der ist und bleibt ein ewiger Zweiter!"}]'::jsonb, ''),
  ('dea-growla-fingald-ia-untas-klaadl', 'Dea Growla fingald ia untas Klaadl!', '', '', '', '', 'Der Grabbler fingerlt ihr unters Kleid!', '[{"kategorie": "", "text": "Der Grapscher fummelt unter ihrem Kleid!  2. Der Fingerfuchs nestelt unter ihrem Kleid herum!  3. Der Fummel-Heini ist unter ihrem Kleid zugange!"}]'::jsonb, ''),
  ('wos-fiara-graffl', 'Wos fiara Graffl!', '', '', '', '', 'Was für ein Graffel!', '[{"kategorie": "wörtlich", "text": "\"Was für ein Plunder!\"   2. Was für ein Krempel!  3. Was für ein Schrott!"}]'::jsonb, ''),
  ('fia-des-gaunze-grafflweak-gib-i-da-ned-amoi-an-kilo', 'Fia des gaunze Grafflweak gib I da ned amoi an Kilo!', '', '', '', '', 'Für das ganze Graffelwerk gebe ich dir nicht einmal einen Kilo!', '[{"kategorie": "wörtlich", "text": "\"Für den ganzen Plunder gebe ich dir nicht einmal 100 Euro!\"  2. Für das gesamte Zeug zahle ich dir keine 100 Euro!  3. Für den ganzen Krempel kriegst du keine 100 Euro von mir!"}]'::jsonb, ''),
