  ('i-vaschdee-nix-es-grammaed-in-da-leitung', 'I vaschdee nix, es grammäd in da Leitung!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich verstehe nichts, es grammelt in der Leitung!', '[{"kategorie": "wörtlich", "text": "\"Ich verstehe nichts, es grummelt in der Leitung!\"  2. Ich verstehe nichts, es rauscht in der Leitung!  3. Ich verstehe nichts, es knackt in der Leitung!"}]'::jsonb, ''),
  ('in-mein-moong-grammaeds', 'In mein Moong grammäds!', '', '', '', 'Wiener Sprüche, die sitzen!', 'In meinem Magen grammelt es!', '[{"kategorie": "wörtlich", "text": "\"In meinem Magen rumort es!\"  2. Mein Magen rebelliert!  3. In meinem Magen grummelt es!  4. Mein Magen knurrt!"}]'::jsonb, ''),
  ('graummaed-voi', 'graummäd voi', '', '', '', '', 'gerammelt voll', '[{"kategorie": "wörtlich", "text": "\"gerappelt voll\" (vom mittelhochdeutschen \"ramen\"=\"drängen\")"}, {"kategorie": "allg.", "text": "prallvoll, rappelvoll, gesteckt voll, zum Bersten voll, [[bummvoi]], [[gschoodad]] voi, [[gschdeckd]] voi"}]'::jsonb, 'Im Summa san olle Heirichn gschdeckd voi!'),
