  ('a-gflochde', 'a Gflochde', '', '', '', '', 'eine Geflachte', '[{"kategorie": "wörtlich", "text": "\"Ohrfeige mit der flachen Hand\" (vom mittelhochdeutschen \"vlach\"=\"flach\")"}, {"kategorie": "allg.", "text": "Schlag mit der offenen Hand ins Gesicht, [[Dachtel]], [[Watschen]]"}]'::jsonb, ''),
  ('a-gflochde-is-imma-no-bessa-ois-a-flack', 'A Gflochde is imma no bessa ois a Flack!', '', '', '', '', 'Eine Geflachte ist immer noch besser als ein Flack!', '[{"kategorie": "wörtlich", "text": "\"Lieber eine leichte Klatsche als eine saftige Watsche!\"  2. Ein leichter Schlag ins Gesicht ist immer noch besser als eine donnernde Ohrfeige!  3. Ein zarter Klaps mit der offenen Hand ist immer noch besser als eine gewaltige [[Däädschn]]!"}]'::jsonb, 'a Gflochde'),
  ('si-a-gfrea-auf-da-noosn-hoin', 'si a Gfrea auf da Noosn hoin', '', '', '', '', 'sich ein Gefrör auf der Nase holen', '[{"kategorie": "wörtlich", "text": "\"sich eine Frostbeule auf der Nase holen\""}, {"kategorie": "", "text": "sich die Nase abfrieren"}, {"kategorie": "", "text": "sich einen Frostfleck auf der Nase einhandeln"}]'::jsonb, ''),
