  ('fix-gramatantn', 'Fix Gramatantn!', '', '', '', '', 'Fix Gramatanten', '[{"kategorie": "wörtlich", "text": "\"Verflixt und zugenäht!\" (Kompositum aus [[Fix]]=Kurzform für \"Kruzifix\" und [[Gramatanten]]=Verballhornung von [[Gramadanzen]] [=Faxen])"}, {"kategorie": "Fluch, allg. im Sinne von", "text": "\"Himmel, Arsch und Zwirn!\"  3. \"Verdammt und zugenäht\""}]'::jsonb, ''),
  ('den-haums-griassn-lossn', 'Den haums griassn lossn!', '', '', '', '', 'Den haben Sie grüßen lassen!', '[{"kategorie": "", "text": "Die Dummheit lässt grüßen!  2. Ein Narr bleibt ein Narr!  3. Ein Narr bleibt sich ewig treu!"}]'::jsonb, ''),
  ('tirola-greesdl', 'Tirola Greesdl', '', '', '', '', 'Tiroler Gröstl', '[{"kategorie": "", "text": "\"Tiroler Gröstl\" (Hausmannskostklassiker der Wiener Küche)"}, {"kategorie": "", "text": "Speise aus Kartoffeln, Fleisch, Zwiebeln, Knoblauch, etc., in der Pfanne gebraten (\"geröstet\"), mit einem Spiegelei \"on top\""}]'::jsonb, ''),
